import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"The expression editor","description":"Token view, inserting values, sample result — the \\"Edit an expression\\" dialog.","frontmatter":{"title":"The expression editor","description":"Token view, inserting values, sample result — the \\"Edit an expression\\" dialog."},"headers":[],"relativePath":"en/apptivescript/editor.md","filePath":"en/apptivescript/editor.md","lastUpdated":1787319236000}'),r={name:"en/apptivescript/editor.md"};function n(i,e,d,l,h,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="the-expression-editor" tabindex="-1">The expression editor <a class="header-anchor" href="#the-expression-editor" aria-label="Permalink to &quot;The expression editor&quot;">​</a></h1><p>You don&#39;t write expressions into a blank text field — you write them into an editor that helps along: it shows field names instead of ids, offers the right functions, and calculates the result as a preview.</p><h2 id="where-it-shows-up" tabindex="-1">Where it shows up <a class="header-anchor" href="#where-it-shows-up" aria-label="Permalink to &quot;Where it shows up&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Place</th><th>How to get there</th></tr></thead><tbody><tr><td><strong>Formula</strong> column</td><td>Under <em>Formula</em> in the field settings</td></tr><tr><td><strong>Text field of a Flow step</strong></td><td>Click an already-inserted value — the <em>Edit an expression</em> dialog opens for that block</td></tr><tr><td><strong>Flow transition</strong></td><td>In the <em>Only continue if …</em> dialog, under <em>Advanced logic</em></td></tr></tbody></table><h2 id="blocks-or-text" tabindex="-1">Blocks or text <a class="header-anchor" href="#blocks-or-text" aria-label="Permalink to &quot;Blocks or text&quot;">​</a></h2><p>An expression can be edited in two views. You switch between them via the menu next to the label:</p><table tabindex="0"><thead><tr><th>Menu item</th><th>What you see</th></tr></thead><tbody><tr><td><strong>Show formula as text</strong></td><td>The expression as plain text — for copying, pasting, and larger rewrites</td></tr><tr><td><strong>Show formula as tokens</strong></td><td>The expression as colored blocks — fields with their names, functions, values</td></tr></tbody></table><p>The token view is the more readable one: instead of <code>fieldValue(&#39;64f2a1c0…&#39;)</code>, it shows the field name in blue. Either way, what gets stored is the same.</p><div class="tip custom-block"><p class="custom-block-title">Use the text view for expressions from elsewhere</p><p>The easiest way to bring in an expression from this documentation or from another Grid is to paste it in the text view. Then switch back to tokens — if the conversion succeeds, the expression was valid.</p></div><h2 id="inserting-values-and-functions" tabindex="-1">Inserting values and functions <a class="header-anchor" href="#inserting-values-and-functions" aria-label="Permalink to &quot;Inserting values and functions&quot;">​</a></h2><p>Below the input field is the picker, with several tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Contents</th></tr></thead><tbody><tr><td><strong>Search</strong></td><td>The Grid&#39;s fields, the operators, and the functions for the <strong>current</strong> type</td></tr><tr><td><strong>Flow</strong></td><td>The results of this Flow&#39;s steps, and the Flow variables</td></tr><tr><td><strong>Date</strong> · <strong>Numbers</strong> · <strong>String</strong> · <strong>Boolean</strong> · <strong>Collection</strong></td><td>Every function of the respective type, regardless of the current expression</td></tr></tbody></table><p>A click inserts the entry at the cursor position. In a Flow step&#39;s text fields, you can also <strong>drag</strong> values from the picker to the desired spot.</p><div class="warning custom-block"><p class="custom-block-title">The <em>Search</em> tab changes as you type</p><p>It shows the functions for the type the expression is <strong>currently</strong> returning. After <code>fieldValue(&#39;title&#39;)</code> it shows text functions; after <code>.isEmpty()</code>, boolean ones. If you&#39;re looking for a function that isn&#39;t there, you usually have the wrong type in front of you — not the wrong spelling.</p><p>The operators <code>+ - * /</code> only appear when the expression returns a number.</p></div><div class="tip custom-block"><p class="custom-block-title">The Flow tab needs a test run</p><p>The step results come from the last test run. Without one, the tab stays empty and the editor says so too: <em>You need to test the Flow first</em>. → <a href="/en/flows/testen">Testing Flows</a></p></div><h2 id="sample-result-and-type" tabindex="-1">Sample result and type <a class="header-anchor" href="#sample-result-and-type" aria-label="Permalink to &quot;Sample result and type&quot;">​</a></h2><p>Below the input field is the <strong>Sample result</strong> — the expression evaluated against real data: in a Formula column, against an entry from the Grid; in a Flow, against the values from the test run. Above it is the detected type, e.g. <em>Type: String</em>.</p><p>The type is the more important of the two. It determines which functions are possible next, and in a Formula column, which result types are available under <em>Display result as</em>.</p><div class="warning custom-block"><p class="custom-block-title">An empty sample result is not proof of anything</p><p>The sample result is calculated <strong>in the browser</strong>; the production evaluation runs on the server. The two don&#39;t always agree: a number of functions stay blank in the preview even though the same formula does calculate in production.</p><table tabindex="0"><thead><tr><th>Expression</th><th>Preview</th><th>In the Formula column</th></tr></thead><tbody><tr><td><code>(100 / 3).round(2)</code></td><td>blank</td><td><code>33.33</code></td></tr><tr><td><code>today().addDays(1)</code></td><td>blank</td><td>tomorrow&#39;s date</td></tr><tr><td><code>3.asString()</code></td><td>blank</td><td><code>3</code></td></tr><tr><td><code>&#39;a,b,c&#39;.match(&#39;[a-z]&#39;)</code></td><td>blank</td><td>evaluates</td></tr></tbody></table><p>This mainly affects <strong>date calculations</strong>, <strong>rounding</strong>, and some <strong>conversions</strong> — and by extension the interface&#39;s relative date filters, which are exactly this kind of expression.</p><p>So rely on the <strong>type display</strong> instead, and check the result against a real entry or in a test run. That said, the reverse also holds: an expression that does show a result in the preview also works fine in production.</p></div><h2 id="applying-and-errors" tabindex="-1">Applying and errors <a class="header-anchor" href="#applying-and-errors" aria-label="Permalink to &quot;Applying and errors&quot;">​</a></h2><p>The expression is applied when you leave the field or press Enter. If it can&#39;t be parsed, the message appears below the field — and the text you entered stays as plain text instead of being converted into blocks.</p><p><strong>Blocks instead of text are the confirmation that the expression could be read.</strong> If your input stays unchanged, something is wrong.</p><p>The messages are in English and name internal type names; what they mean is listed under <a href="/en/apptivescript/schreibweise#editor-error-messages">Syntax</a>.</p><h2 id="grid-fields-in-the-html-block-and-the-javascript-step" tabindex="-1">Grid fields in the HTML block and the JavaScript step <a class="header-anchor" href="#grid-fields-in-the-html-block-and-the-javascript-step" aria-label="Permalink to &quot;Grid fields in the HTML block and the JavaScript step&quot;">​</a></h2><p>The <a href="/en/seiten/html-bloecke">HTML block</a> and the Flow step <strong>JavaScript</strong> don&#39;t have an expression editor — they have a code editor. You can still insert Grid fields there too:</p><blockquote><p><em>Press Ctrl + Space to insert Grid fields</em></p></blockquote><p>The suggestion list shows the field names and inserts <code>{{fieldValue(&#39;&lt;field id&gt;&#39;)}}</code> — with curly braces, because these editors mix text and expressions. The same list appears as soon as you type <code>field</code>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptivescript/bedingungen">Building conditions</a> — comparisons, AND/OR, branches</li><li><a href="/en/apptivescript/werte-referenzieren">Referencing values</a> — what an expression starts with</li><li><a href="/en/referenz/apptivescript-funktionen">Function reference</a> — every function by type</li><li><a href="/en/grids/berechnete-felder">Computed fields</a> · <a href="/en/flows/daten-zwischen-schritten">Passing data between steps</a></li></ul>',29)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
